function Activity({data,setEditor}:{data:DataSet;setEditor:(x:{entity:string;row?:Row})=>void}){const[filter,setFilter]=useState("All");const categories=["All","Revenue","Clients","Projects","Content","Finance","Knowledge","Tasks","AI"];const activities=(data.activityLogs??[]).filter(x=>filter==="All"||x.category===filter);return <div className="content section-view"><section className="section-intro"><p className="eyebrow purple">FOUNDER ACTIVITY TIMELINE</p><h2>A live record of how the business moves.</h2><p>Every significant save, update and completion is logged and linked to its originating record.</p></section><div className="activity-filters">{categories.map(category=><button className={filter===category?"active":""} key={category} onClick={()=>setFilter(category)}>{category}</button>)}</div><section className="panel timeline">{activities.map(item=>{const origin=(data[String(item.entity)]??[]).find(x=>x.id===item.recordId);return <button key={item.id} onClick={()=>origin&&configs[String(item.entity)]&&setEditor({entity:String(item.entity),row:origin})}><span className={`timeline-icon ${String(item.category).toLowerCase()}`}>✦</span><div><strong>{rowLabel(item)}</strong><small>{String(item.category)} · {new Intl.DateTimeFormat("en-NZ",{day:"numeric",month:"short",hour:"numeric",minute:"2-digit"}).format(new Date(String(item.createdAt)))}</small></div><em>{origin?"Open record →":"System event"}</em></button>})}{!activities.length&&<div className="empty-inline"><p>No activity in this filter.</p></div>}</section></div>}

