function RevenueSummary({metrics}:{metrics:Metrics}){const max=Math.max(1,...metrics.history.map(x=>x.value));return <><section className="stat-grid"><Metric label="Monthly goal" value={money(metrics.goal)} note={`${metrics.goalProgress}% achieved`} tone="violet" progress={metrics.goalProgress}/><Metric label="Paid revenue" value={money(metrics.revenue)} note={metrics.month} tone="blue" progress={metrics.goalProgress}/><Metric label="Weighted forecast" value={money(metrics.weightedPipeline)} note={`Pipeline ${money(metrics.pipelineValue)}`} tone="magenta" progress={metrics.pipelineValue?metrics.weightedPipeline/metrics.pipelineValue*100:0}/><Metric label="Pending invoices" value={money(metrics.outstanding)} note={`${metrics.openInvoices} outstanding`} tone="amber" progress={metrics.goal?metrics.outstanding/metrics.goal*100:0}/></section><section className="panel chart-panel"><PanelHeader eyebrow="6-MONTH VIEW" title="Revenue history"/><div className="bar-chart">{metrics.history.map(x=><div key={x.period}><span>{money(x.value)}</span><i style={{height:pct(x.value/max*100)}}/><small>{new Date(`${x.period}-01`).toLocaleDateString("en-NZ",{month:"short"})}</small></div>)}</div></section></>}
function FinanceSummary({metrics}:{metrics:Metrics}){return <section className="stat-grid"><Metric label="Income" value={money(metrics.revenue)} note={metrics.month} tone="violet" progress={metrics.goalProgress}/><Metric label="Expenses" value={money(metrics.monthExpenses)} note="This month" tone="blue" progress={metrics.revenue?metrics.monthExpenses/metrics.revenue*100:0}/><Metric label="Profit" value={money(metrics.profit)} note="Before tax" tone="magenta" progress={metrics.revenue?metrics.profit/metrics.revenue*100:0}/><Metric label="Cash due" value={money(metrics.outstanding)} note={`${metrics.openInvoices} invoices`} tone="amber" progress={metrics.goal?metrics.outstanding/metrics.goal*100:0}/></section>}
